insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU''s 2026-27 handbook says all NIL activity must be disclosed through ''FAU''s Disclosure platform'' but does not name it or give a deadline.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU requires prior express written permission to use FAU, conference or NCAA marks or facilities in NIL, and says the going rate is paid.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU tells international students to contact the International Student Services Office before any NIL activity.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU staff may seek and connect NIL opportunities for current athletes (handbook list ''FAU Institutional Staff Members MAY'').');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'The Opendorse Owls Marketplace is the marketplace FAU links to in 2025 and 2026.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', '''NIL in Paradise is the official collective'' comes from a 2024 page. Current status is not confirmed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The handbook does not name the disclosure platform. The handbook separately mentions Opendorse as a personal branding tool and Teamworks for employment forms, but neither is called the NIL disclosure platform.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'Two live FAU pages disagree on collectives. The 2021-URL page lists Paradise Collective, Owl Collective and Prowlerz Club. The 2024 page names NIL in Paradise as the official collective. Both are dated before July 2025.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The Agents page (2023) tells agents to send registrations to John Stephenson, who is not on the current compliance staff list. The current compliance lead listed is Garrett Franskousky.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The 2024-25 handbook had a list ''FAU Institutional Staff Members MAY NOT'' (promise NIL in recruiting, donate to NIL entities). That list is not in the 2026-27 handbook.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'FAU''s pages say the settlement ''opens the door for revenue sharing'' but no FAU page read states that FAU pays revenue share or how much. No school-payments rule is recorded.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'Compliance staff phone numbers and the street address come from a WebFetch summary of the staff directory, not raw text.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The site navigation has one Swimming and Diving link. It is listed under both men and women here and should be checked. The compliance page still names AAC, CUSA and ASUN.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'Handbook quotes were cleaned of stray spaces added by PDF text extraction (for example ''Student - athletes'').');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'TheLinkU (2023) status at FAU is not confirmed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Platform: Opendorse is named for disclosure only on the undated Donors page. The handbook also calls Opendorse a personal branding tool. A person should confirm it is still the disclosure platform for 2026-27.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Deadline: no FAU page read states a disclosure deadline.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Agent contact: the only named recipient is John Stephenson on two 2023 documents. Treat as likely outdated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Handbook page 37 says media contact not arranged by the Communications Office is not allowed unless it is part of NIL obligations, and asks athletes to tell their communication officer even then.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: FAU pages checked for a formal policy: fau.edu/regulations index, fau.edu/policies index and the university Trademark Guidelines page. None showed an NIL item by title. The regulation chapter PDFs were not opened.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Compliance sub-pages for Student-Athletes, Coaches and Staff, and Recruits contain no NIL text.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 correction: disclosure-required rule and disclosure_workflow: the platform is named on an official FAU page. The Donors compliance page says ''Student-athletes must disclose all NIL activities via Opendorse''. Update platform_name to Opendorse with a note that the page is undated (2023 URL) and the 2026-27 handbook does not name it. Remove ''Name of FAU''s NIL disclosure platform'' from not_found. A deadline is still not found.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 correction: agents rule: the registration form was opened. Both the Agents page and the form name John Stephenson (form prints [email on the official page]). He is not on the current staff directory, which lists Garrett Franskousky, Aliana Bennazar and J.R. Kidd. Keep the general office email as the contact and keep the outdated flag.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 correction: collectives rule and ''NIL in Paradise'' program: nilinparadise.com now redirects to a TheLinkU donation page for FAU. FAU''s own ''NIL in Paradise'' page is still live and links to TheLinkU. Status stays unconfirmed by a current FAU statement, but the TheLinkU program entry should not be treated as ended.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Ambiguity ''Compliance staff phone numbers and the street address come from a WebFetch summary'' can be cleared. Phones, emails, titles and the 777 Glades Rd address were confirmed in raw text.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 correction: school-staff-involvement rule: the ''MAY'' list has four bullets. The third, ''Educate student-athletes, boosters and prospective student-athletes'', was not quoted. Wording of the other handbook quotes is confirmed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found ''Booster guidance on NIL'' should be removed. The Donors page has a short NIL section for boosters.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'conflict', 'FAU ''NIL at Florida Atlantic'' page lists three collectives. FAU ''NIL in Paradise'' page names a single official collective.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'not_found', 'Name of FAU''s NIL disclosure platform and any deadline');
