insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'FIU requires disclosure through the INFLCR app before an NIL agreement is entered (2026-2027 handbook).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'Deals over $10,000 need an extra review by the Athletics Director.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'FIU logos, trademarks and any part of the uniform need approval from two FIU offices, a written agreement and license or sponsorship fees.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'FIU bans endorsements of illegal drugs, tobacco including e-cigarettes, anabolic steroids, gambling, firearms and sexually oriented businesses.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'NIL contracts may not run past the athlete''s time in the FIU athletics program.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'FIU facilities must be arranged and approved through FIU Athletics, with rental rates.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'Policy 910.001 was last revised May 8, 2023, before the House settlement. The 2026-2027 handbook repeats its text, so it is treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'Procedure 910.001a is ''temporarily rescinded'' in the policy PDF, yet the 2026-2027 handbook still lists procedure steps (INFLCR app, approval request form, 10 days to resolve conflicts).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The handbook sentence on review timing is garbled: ''All transactions will be reviewed by the Sr. Associate Athletic Director shall be given within five (5) business days of receipt of the Name, Image and Likeness Approval Request form.''');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The handbook''s NIL Go text includes old dates (deals before June 7, 2025 reported by July 1, 2025). It restates the national process and is not recorded as an FIU rule.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The Panther Exchange (2023), The Blueprint Collective (2023) and ROAR (2021) come from pre-July 2025 releases. Current status is not confirmed. fiusports.com/exchange still redirects to INFLCR.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The Panther Club page says FIU and other Division I schools ''are able to offer increased benefits to student-athletes through revenue sharing'' as of July 1, 2025. It does not say whether or how much FIU pays. No school-payments rule is recorded.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'Kevin D. Kendrick''s title reads slightly differently in a search result (''Senior Associate AD, Compliance & Deputy Title IX Coordinator'').');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'Sports list is from site navigation links. Cross country was not in the links seen and should be checked.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'No FIU guidance for international athletes on NIL was found in the handbook or policy.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: No newer version of Policy 910.001 was located in the public sources reviewed as of October 4, 2026. The policy still cites Section 1006.74, Board of Governors Regulation 6.022 and the NCAA interim NIL policy.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The handbook is the newer document (August 2026). It names the INFLCR app and also restates the national NIL Go steps with old 2025 dates. A person should confirm whether FIU still wants disclosure in INFLCR as well as NIL Go.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The handbook agents section says an athlete may not agree to be represented by an agent ''in the marketing of your athletic ability or reputation'' until after the last contest. It does not carve out NIL agents. Flag as unclear.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Agent registration forms were not located on the FIU Compliance page.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Blueprint Collective site still loads and calls itself the official NIL collective of FIU. No current FIU page naming it was found. Keep status unknown.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The FIU Athletics Brand Guide 2024-25 PDF linked from the athletics site is image-only. Its text could not be read with pdf.js. A person should check it for NIL or logo approval wording: https://fiusports.com/documents/2024/12/19/FIU_Athletics_Brand_Guide_2024-25.pdf');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 correction: team-activities rule: the examples in the summary (study hall, team promotional events, compliance meetings) come from the handbook, not from Policy 910.001 Definitions as cited. The policy list is practice, strength and conditioning, competitions, film study, skill instruction, compliance meetings, host activities, recruiting, fundraising and promotional activities, community service, team travel, media activities and team building. Cite the handbook for the examples or reword.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Panther Exchange program: change current from ''unknown'' to true. The FIU address still redirects to a live exchange page.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Ambiguity on Procedure 910.001a: confirmed. No procedure text is published and no replacement is in the policy library. The rescission page carries its own last revision date of March 15, 2023 and refers to the procedure dated August 16, 2022.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Kevin D. Kendrick: the staff page title reads ''Senior Associate AD, Compliance & Deputy Title IX Coordinator'' and styles him ''Dr.''. The Compliance page reads ''Senior Associate Athletic Director/Compliance & Title IX Deputy Coordinator''. Both are official. Pick one.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'October 4 correction: Policy scope not recorded: ''This policy applies to all current and prospective intercollegiate student-athletes.''');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'conflict', 'Policy 910.001 says to disclose ''through the reporting system established by FIU'' without naming it. The handbook names the INFLCR app and also describes NIL Go.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'manual_review', 'Class E, low risk: FIU Procedure 910.001a Student-Athlete Name, Image, and Likeness (https://policies.fiu.edu/files/910.001a). Marked temporarily rescinded. No text published.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'manual_review', 'Class B, low risk: FIU agent and financial planner registration forms. Not located under the Athletics Compliance tab.');
