insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-am-university'), NULL, NULL, 'claim', 'Rattlers Local Exchange is still linked in the athletics site menu, but the announcement is from 2022. Current status was not confirmed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-am-university'), NULL, NULL, 'claim', 'Compliance staff names and emails are as printed in the athletics staff directory on October 3, 2026.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-am-university'), NULL, NULL, 'ambiguity', 'The famu.edu NIL guidance is undated and does not mention the House settlement, revenue sharing or NIL Go. Its linked checklist PDF has a server file date of August 2024, so the guidance may predate July 2025.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-am-university'), NULL, NULL, 'ambiguity', 'The INFLCR (2021) and Rattlers Local Exchange (2022) releases are pre-House settlement. Whether FAMU still uses INFLCR for disclosure is not confirmed.');
