insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'left_off_page', 'JU says financial aid questions tied to NIL pay should go to Jacksonville University Student Financial Services, because Pell Grant or need-based aid could be affected. Reason: A financial aid referral, not a parent or guardian rule. Left off the page.');
