insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'No dedicated NIL staff member is named. Compliance staff are listed as the general contact.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: Policy 5.0110P still cites Fla. Stat. 1006.74 and Board of Governors Regulation 6.022 as its basis, and the handbook opens with ''The state of Florida law permits''. A person should check these against current state law wording.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The policy says Pell Grant or need based aid ''could be impacted'' by NIL pay and sends questions to One-Stop. It also says NIL may have tax implications.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The policy says the University and its employees, including coaches, are not liable for damage to an athlete''s NIL earning ability from routine athletics decisions.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The handbook says NIL is expected to ''align with UNF values'' and that education comes from the Student-Athlete Center for Excellence.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Reference Guide image has no printed date. The 2025-11-03 date is from the file path only.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 re-check: The handbook Boosters/Osprey Club page has no NIL text. No UNF collective was named on any page read.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: school_policy and policy_search: a longer formal policy exists. UNF Policy 5.0110P ''Intercollegiate Athletes - Name, Image and Likeness'' (effective 10/25/21, revised 01/20/26) should be the school policy. The one page Reference Guide is a summary of it.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found ''Uniform or team-issued gear rule for NIL content'' should be removed. Both the policy and the handbook cover uniforms.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found ''A UNF licensing office contact or NIL logo approval form'': the route is the NIL Logo Request workflow in the compliance software. No public form or named licensing office was found.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: team-activities rule: the ''on call'' sentence is in the guide''s list ''Impermissible for Institutions Under NCAA Rules'' (''Allow SA to promote their NIL activity while on call for required athletically related activities''). It limits what the school may allow. Reword the summary.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: agents rule: add that agents must also register with the UNF Compliance Office before contacting an athlete (handbook).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: international-athletes rule: the handbook asks F-1 athletes to seek guidance and approval before any NIL activity. Consider changing the answer to only_with_approval.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: Ambiguity ''unclear if deals must also be entered in Teamworks'': logo and facility requests go through workflows in the compliance software (the Compliance Corner page names Teamworks Compliance & Recruiting). Deal reporting is through NIL Go per the guide and ''as directed by the NCAA and/or the College Sports Commission'' per the policy.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: s7 Osprey Boosters release: Talent Fund wording is confirmed in raw text. The read_method caveat can be cleared.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: s3 quote ''Any student-athletes requesting to use university facilities can do so through the NIL Facility Request workflow on Teamworks Compliance & Recruiting.'' is confirmed in raw text. read_method can change from extraction to raw_text.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'ambiguity', 'October 4 correction: All Reference Guide quotes were checked against the image and match.');
