insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-gulf-coast-university'), NULL, NULL, 'left_off_page', 'FGCU''s page says an athlete under 18 must have an NIL contract approved under state statutes 743.08 and 743.09. Reason: Restates Florida law on contracts with minors on a 2021 page. Left off the page.');
