insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'Only about one page of the six page NIL policy was read. Rules on agents, boosters, logos, facilities, prohibited categories, international athletes and penalties may be in the unread pages.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'The policy viewer showed a last saved time of 07/30/2026, while the effective date is September 16, 2025. The policy may have been revised.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'The policy took effect in September 2025, before Stetson''s House opt-in begins in 2026-27. It is unclear if NIL Go disclosure applied to Stetson athletes during 2025-26.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'Quotes from the policy were read by eye from a rendered Word page. One quote keeps a stray space (''student- athlete''s'') as shown on screen.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'The Compliance Resource Center links a 2019-20 Policies & Procedures Manual, which predates NIL.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Pages read in full: 1, 2, 3, 4, 5 and 6. All text was read by eye from screenshots (read_method visual), so a human should spot check quotes against the viewer. Quotes keep the on-screen wording, including ''student- athlete’s'' and ''a student-athletes grant-in-aid''.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The Purpose section still says the policy ensures compliance with ''current NCAA interim policies and Florida state legislation'', and the Policy section cites Section 1006.74, Florida Statute. The policy does not use the words House settlement or revenue sharing.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The policy bars pay ''in exchange for their athletics participation or achievements''. Stetson''s December 18, 2025 release says it opts in to the House settlement from 2026-27. The policy text has not been revised since September 16, 2025.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Not addressed in the policy: boosters (only ''associated entities or individuals'' in the $600 reporting sentence), collectives, uniforms, team-issued gear, product categories such as gambling or alcohol, and any penalty beyond withholding institutional assistance and services.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Policy History table: September 16, 2025 Revised (Athletics Director). September 6, 2024 Revised to include updated NCAA legislation on disclosure timelines and professional service providers. November 1, 2023 Revised for international student-athletes. March 17, 2023 Revised for prospective student-athletes and Florida law. February 15, 2022 Initial Approval (VP Operations).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Frequency of Review: the policy says it is reviewed every three years, or sooner when conference, NCAA, Florida or federal rules change.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The policy links NIL GO, the WORLD office, the Office of Student Financial Planning, the exclusive sponsors list and the Branding and Style Guides. Link targets could not be read from the viewer.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Hatters Collective Group (hatterscollectivegroup.com) and Hatters Prime (hattersprime.com) are live third party sites. No official Stetson page read names them.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 correction: disclosure-required: the quote ended at ''NIL''. The full sentence ends ''to NIL GO.'' Add the $600 total threshold and the five business day deadline. Replace the rule with the new one.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 correction: disclosure_workflow: recipient is NIL GO. deadline_text should be ''within five business days of execution of a noninstitutional name, image or likeness contract or agreement to payment terms''. Threshold is a total value of $600 or more. Written documentation must be submitted to NIL GO.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 correction: school-logos-marks: change from not_addressed. The policy says use of Stetson''s name, marks or symbols must follow the Branding and Style Guides.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 correction: ambiguities: remove ''Only about one page of the six page NIL policy was read''. All six pages are now read.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'stetson-university'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found: remove facility-use, prohibited categories and international athlete items. The policy covers all three.');
